&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;6&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;actuators&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;(brushed and brushless motors, servomotors, magnetic coupling) and sensors used in aerospace or mechatronics applications&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;7&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Background in&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Battery Management Systems&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;and power circuit design&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;8&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;environmental testing&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;requirements (vibration, shock, temperature, humidity) for aerospace applications&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;9&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Familiarity with&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;FEA (Finite Element Analysis)&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;for structural and thermal analysis&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;10&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Understanding of&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;airworthiness certification&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;processes and safety assessment methodologies&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Join Helsing and work with world-leading experts in their fields&lt;/span&gt;&lt;span data-ccp-props=&quot;{&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Helsing’s work is important. You’ll be directly contributing to the protection of democratic countries while balancing both ethical and geopolitical concerns&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The work is unique. We operate in a domain that has highly unusual technical requirements and constraints, and where robustness, safety, and ethical considerations are vital. You will face unique Engineering and AI challenges that make a meaningful impact in the world&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Our work frequently takes us right up to the state of the art in technical innovation, be it reinforcement learning, distributed systems, generative AI, or deployment infrastructure. The defense industry is entering the most exciting phase of the technological development curve. Advances in our field of world are not incremental: Helsing is part of, and often leading, historic leaps forward&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;In our domain, success is a matter of order-of-magnitude improvements and novel capabilities. This means we take bets, aim high, and focus on big opportunities. Despite being a relatively young company, Helsing has already been selected for multiple significant government contracts&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We actively encourage healthy, proactive, and diverse debate internally about what we do and how we choose to do it. Teams and individual engineers are trusted (and encouraged) to practice responsible autonomy and critical thinking, and to focus on outcomes, not conformity. At Helsing you will have a say in how we (and you!) work, the opportunity to engage on what does and doesn’t work, and to take ownership of aspects of our culture that you care deeply about&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&quot;What-we-offer&quot; data-renderer-start-pos=&quot;3238&quot;&gt;&lt;strong&gt;&lt;span id=&quot;6afa48f9-b797-428b-aa69-0bc8163b3593&quot; data-renderer-mark=&quot;true&quot; data-mark-type=&quot;annotation&quot; data-mark-annotation-type=&quot;inlineComment&quot; data-id=&quot;6afa48f9-b797-428b-aa69-0bc8163b3593&quot;&gt;What we offer&lt;/span&gt;&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A focus on outcomes, not time-tracking&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;A generous compensation and benefits package (in addition to base salary) that includes, but may not be limited to, insurance coverage (medical and travel), flexible paid time off, paid holidays, and remote and/or hybrid work available depending on position. All compensation and benefits are subject to the terms and conditions of the underlying plans or programs, as applicable and as may be amended, terminated or superseded from time to time.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;Growth toward global roles in our Finance organization&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The base salary offered to the successful candidate will be&amp;nbsp;determined&amp;nbsp;by a variety of factors including relevant experience, qualifications, education, skill level, interview performance, and the level and scope of the position.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559685&amp;quot;:0,&amp;quot;335559738&amp;quot;:180,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;Helsing is an Equal Opportunity Employer. We will consider all qualified applicants without regard to race, color, sex, sexual orientation, gender identity, national origin, age, disability, protected veteran status, genetics, or any other characteristic protected by applicable federal, state, or local law. &amp;nbsp;&lt;span data-contrast=&quot;none&quot;&gt;Please do not submit personal data revealing racial or ethnic origin, political opinions, religious or philosophical beliefs, trade union membership, data concerning your health, or data concerning your sexual orientation.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;Helsing&#39;s Candidate Privacy and Confidentiality Regime can be found &lt;a href=&quot;https://helsing.ai/candidate-privacy-and-confidentiality-regime/&quot; target=&quot;_blank&quot;&gt;here&lt;/a&gt;.&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;&lt;/div&gt;

lsvp-weee:greenhouse:7514868003.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;&lt;strong&gt;About Weee!&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Weee! is the largest and fastest-growing ethnic e-grocer in the United States, operating in one of the largest underserved categories in retail with affordable access to exciting ethnic food. By partnering with local suppliers, redesigning the value chain and leveraging social buying, Weee! is reshaping the grocery business entirely. You can read more about us on &lt;/span&gt;&lt;a href=&quot;https://www.businessinsider.com/weee-softbank-grocery-delivery-425-million-series-e-4-billion-valuation-2022-2&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Business Insider&lt;/span&gt;&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;, &lt;/span&gt;&lt;a href=&quot;https://www.reuters.com/markets/us/e-grocer-weee-raises-425-million-funding-round-led-by-softbank-2022-02-28/&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Reuters&lt;/span&gt;&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt; and &lt;/span&gt;&lt;a href=&quot;https://techcrunch.com/2022/02/28/weee-delivers-second-big-funding-round-in-a-year-this-time-backed-by-softbank/&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;TechCrunch&lt;/span&gt;&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Weee! is headquartered in Fremont, CA, and is currently available coast to coast with exceptional growth (5x YoY) across geographies, categories and ethnicities. We have raised $800M+ in funding to date from leading investors including &lt;a href=&quot;https://visionfund.com/portfolio&quot; target=&quot;_blank&quot;&gt;Softbank Vision Funds&lt;/a&gt;, &lt;/span&gt;&lt;a href=&quot;https://techcrunch.com/2020/08/17/weee-35-million-raise-from-dst/&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;DST&lt;/span&gt;&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;, Blackstone, Tiger Global, Lightspeed Ventures, Goodwater Capital, XVC and iFly. The opportunity now is to join a rocketship as we prepare for the next stage of growth, and an eventual public listing.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;This role is onsite 5 days a week in Landover, MD&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the Role&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The ICQA Specialist II will be responsible for overall inventory accuracy and managing shrinkage , including investigating customer complaint cases related to the inventory issues within the Fulfillment Centers.&amp;nbsp; The location will be in Landover, MD&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Roles &amp;amp; Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead day-to-day work direction for ICQA Cycle Counters and Specialist I associates, including task assignment, productivity monitoring, and coaching&lt;/li&gt;
&lt;li&gt;Conduct advanced inventory discrepancy research and root cause analysis; develop and implement corrective action plans&lt;/li&gt;
&lt;li&gt;Analyze operational trends and build reporting tools using advanced Excel capabilities and tableau capabilities&lt;/li&gt;
&lt;li&gt;Supervise execution of cycle counts, bin audits, and quality checks to ensure operational accuracy and compliance&lt;/li&gt;
&lt;li&gt;Facilitate training for warehouse associates on operational SOPs to improve inventory related metrics&lt;/li&gt;
&lt;li&gt;Plan physical inventory events including planning, execution, and reconciliation&lt;/li&gt;
&lt;li&gt;Improve inventory-related processes and collaborate with department leaders to enhance KPI performance&lt;/li&gt;
&lt;li&gt;Ensure safety, food-safety, and compliance standards are upheld at all times&lt;/li&gt;
&lt;li&gt;Communicate performance results and systemic issues to leadership with clear documentation and recommendations&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Qualifications&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Bachelor’s degree or equivalent experience.&lt;/li&gt;
&lt;li&gt;5+ years of warehouse or operations experience, with at least 2 years focused in inventory management&lt;/li&gt;
&lt;li&gt;Demonstrated experience providing task leadership, mentorship, or people-focused supervision&lt;/li&gt;
&lt;li&gt;Advanced proficiency in spreadsheet and data analytics and visualization&lt;/li&gt;
&lt;li&gt;Strong investigative and analytical skills with the ability to interpret complex data&lt;/li&gt;
&lt;li&gt;Excellent verbal and written communication skills&lt;/li&gt;
&lt;li&gt;Proven ability to work effectively under pressure, handle multiple priorities, and meet deadlines in a fast-paced environment&lt;/li&gt;
&lt;li&gt;Experience supporting process improvement or continuous improvement initiatives preferred&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Requirements&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Ability to work 5 days onsite&lt;/li&gt;
&lt;li&gt;Ability to work &lt;strong&gt;shift schedules&lt;/strong&gt;, including nights, weekends and holidays as business needs&lt;/li&gt;
&lt;li&gt;Must be able to work in &lt;strong&gt;freezer (-10°F to 32°F)&lt;/strong&gt;, &lt;strong&gt;refrigerated&lt;/strong&gt;, and &lt;strong&gt;ambient&lt;/strong&gt; warehouse environments for extended periods&lt;/li&gt;
&lt;li&gt;Must be able to lift and move up to &lt;strong&gt;50lbs&lt;/strong&gt; and perform physically active work throughout the shift&lt;/li&gt;
&lt;li&gt;Ability to stand, walk, bend, and reach for extended durations&lt;/li&gt;
&lt;li&gt;Must demonstrate reliability, adaptability, and resilience in high-volume operational settings&lt;/li&gt;
&lt;li&gt;Ability to reach above shoulder level at 72 inches (6 feet) without assistance&lt;/li&gt;
&lt;li&gt;Ability to work at elevated heights up to 30 feet&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Benefits&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Comprehensive health insurance package, including medical, dental, and vision.&amp;nbsp; PPO/HMO packages&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;401k, 4% company match&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Equity and Bonus&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Vacation, sick and holiday time off&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Monthly mobile stipend&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Monthly Weee! Points credits&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Compensation Range&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;The US base salary range for this full-time position is $53,000 - $63,000&lt;/li&gt;
&lt;li&gt;This role may be eligible to discretionary bonus, incentives and benefits&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Our salary ranges are determined by role, level, and location&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;The range displayed on each job posting reflects the minimum and maximum base salary for new hires for the position across all US locations. Within the range, individual pay is determined by multiple factors like job-related skills, experience and work locations. Your recruiter can share more about the specific salary range during the hiring process.&lt;/p&gt;
&lt;p&gt;Please note that the compensation details listed in US role postings reflect the base salary only, and do not include any variable compensation elements.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Weee! is an equal opportunity employer welcoming&amp;nbsp;all qualified applicants regardless of race, color, religion, sex, sexual orientation, gender identity, national origin, disability status, protected veteran status or any other basis prohibited by law.&amp;nbsp; Discrimination or harassment of any kind is not tolerated at Weee!.&amp;nbsp;If you need to inquire about an accommodation or need assistance with completing the application, please email us at&amp;nbsp;&lt;/em&gt;&lt;a href=&quot;mailto:applicantaccommodation@sayweee.com&quot;&gt;&lt;em&gt;applicantaccommodation@sayweee.com&lt;/em&gt;&lt;/a&gt;&lt;em&gt;.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;For more jobs and to find out more about Weee!, visit our career page: &lt;a href=&quot;https://about.sayweee.com/careers&quot;&gt;https://about.sayweee.com/careers&lt;/a&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;a href=&quot;https://visionfund.com/portfolio&quot; target=&quot;_blank&quot;&gt;Softbank Vision Funds&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.google.com/document/d/1B0nGJBXSOloNJs_-pU_cPFUnQ_Lbhru6IwxvFL79mJc/edit?tab=t.0&quot;&gt;California Employee Privacy Policy Intro/FAQ &amp;nbsp;3.19.2026&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.google.com/document/d/1fbLf8JguJ_Da11Tr9LUfUrbTX9ZiVhz5/edit&quot;&gt;Weee! Privacy Policy for California Employees Applicants Contractors (March 2026)&lt;/a&gt;&lt;/p&gt;&lt;/div&gt;

mbaexchange-bayada:greenhouse:8493457002.descriptionHtml:
&lt;div class=&quot;iCIMS_Expandable_Container&quot;&gt;
&lt;div class=&quot;iCIMS_Expandable_Text&quot;&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;BAYADA Home Health Care&lt;/strong&gt;&amp;nbsp;is currently seeking an experienced&amp;nbsp;&lt;strong&gt;Speech Language Pathologist, SLP, for a full time, part time or per diem&lt;/strong&gt; opportunity performing&amp;nbsp;&lt;strong&gt;home health&lt;/strong&gt;&amp;nbsp;visits for our office located in &lt;strong&gt;Rutland, Vermont.&lt;/strong&gt;.&amp;nbsp;&lt;strong&gt; &lt;/strong&gt;This office services adult and geriatric patients in homes throughout &lt;strong&gt;Windsor and Windham County, Vermont.&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;Prior home care experience as a Speech Language Pathologist, SLP is a plus, but not required. &amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;As a home care Speech Language Pathologist, SLP, you will be an integral member of a multi-disciplinary health care team that provides rehabilitative care and skilled nursing to clients, affording them the opportunity to receive the medical care required to remain at home.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;&lt;iframe src=&quot;https://www.youtube.com/embed/Sxdj52KNt5A&quot; width=&quot;560&quot; height=&quot;314&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Speech Language Pathologist, SLP Responsibilities:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;Make home visits to clients in designated geographic territories.&lt;/li&gt;
&lt;li&gt;Perform thorough evaluations to assess, diagnose, and provide therapeutic interventions for clients who are experiencing speech, language, communication, or swallowing difficulties.&lt;/li&gt;
&lt;li&gt;Develop a treatment plan based on the evaluation, physician’s orders, and recommended goals.&lt;/li&gt;
&lt;li&gt;Continually assess and revise the speech therapy care plan, and participate with BAYADA clinicians in the multidisciplinary care plan, as appropriate.&lt;/li&gt;
&lt;li&gt;Educate and instruct patients, family members, or other patient representatives, in rehabilitative care and activities necessary to promote the client&#39;s health, safety, and independent living.&lt;/li&gt;
&lt;li&gt;Accurately document observations, interventions, and evaluations pertaining to patient care management and services provided, utilizing a state-of-the-art touch pad tablet.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Speech Language Pathologist, SLP Qualifications:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;A current license as a Speech Language Pathologist in Vermont&lt;/li&gt;
&lt;li&gt;Possess a certificate of clinical competence in speech from the American Speech and Hearing Association, or;&lt;/li&gt;
&lt;li&gt;Have the equivalent educational requirements, as indicated by school transcript or diploma, and work experience necessary for such a certificate, and be awaiting the opportunity to take the American Speech-Language-Hearing Association examination for certification, or;&lt;/li&gt;
&lt;li&gt;Have completed the necessary work and education requirements, as indicated by school transcript or diploma, and be in the process of accumulating the necessary supervised work experience required for certification.&lt;/li&gt;
&lt;li&gt;Solid computer skills; prior experience with electronic medical records (EMR) preferred.&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&quot;iCIMS_Expandable_Container&quot;&gt;
&lt;div class=&quot;iCIMS_Expandable_Text&quot;&gt;
&lt;p&gt;&lt;strong&gt;Our employees are our greatest asset:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;To learn more about BAYADA Benefits, &lt;a href=&quot;https://www.bayada.com/benefits/&quot;&gt;click here&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;Enjoy being part of a team that cares and a company that believes in leading with our values.&lt;/li&gt;
&lt;li&gt;Additional Information: Base Pay, depending upon qualifications and subject to negotiation: $46-50 per hour&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Feel confident, safe, and supported with PPE supplies, comprehensive infection prevention protocol, daily pre-screens, and close monitoring of the COVID-19 outbreak.&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;Comprehensive benefits package including paid time off, health, dental, and vision.&lt;/li&gt;
&lt;li&gt;Develop your skills with training and scholarship opportunities.&lt;/li&gt;
&lt;li&gt;Advance your career with specially designed career tracks.&lt;/li&gt;
